import { useState, useEffect } from 'react';
import axios from 'axios';
import CryptoJS from 'crypto-js';

const useMarvelApi = (query) => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!query && !customUrl) return;

    const fetchData = async () => {
      setLoading(true);
      try {
        const ts = new Date().getTime();
        const hash = CryptoJS.MD5(ts + privateKey + publicKey).toString();

        let url;
        if (customUrl) {
          url = customUrl; // Directly use the custom URL if provided
        } else {
          url = `https://gateway.marvel.com:443/v1/public/characters`;
        }

        const response = await axios.get(url, {
          params: {
            apikey: publicKey,
            ts,
            hash,
            ...(customUrl ? {} : { nameStartsWith: query }), // Include query only if not a custom URL call
          },
        });

        setData(response.data.data.results);
      } catch (error) {
        setError(error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, [query, customUrl]); // Add customUrl to the dependency array

  return { data, loading, error };
};

export default useMarvelApi;
